create or replace package body t003_fees as
  c_rate    constant number := 0.01;
  c_min_fee constant number := 1;
  c_max_fee constant number := 10;

  function fee_for(p_amount in number) return number is
    l_calculated_fee number;
  begin
    l_calculated_fee := p_amount * c_rate;
    -- Round to 2 decimal places as per original intent, then apply min/max constraints.
    return greatest(least(round(l_calculated_fee, 2), c_max_fee), c_min_fee);
  end fee_for;
end t003_fees;
